/// Adds one to the count.
    #[inline]
    pub fn increment(&mut self) {
        self.count += 1;
    }

arguments.content:
/// Adds `by` to the count, stopping at the maximum.
    #[inline]
    pub fn increment(&mut self, by: u32) {
        self.count = self.count.saturating_add(by);
    }
